from build_dossier import ROOT,groups,pages,items
import csv
rows=[]
def L(root,ours,keys,phrase,what):
    coords='; '.join(f'{c}:{s:03d} (file lines {pages[c,s]["start"]}–{pages[c,s]["end"]})' for c,s in ours)
    selected=[i for i in items if i['id'] in {groups[k] for k in keys}]
    rows.append({'kind':'folder','from':coords,'to':root,'what':what,'evidence':'Package phrases: '+phrase+'. Items: '+';'.join(groups[k] for k in keys)+'. Package endpoints read directly; root endpoints verified independently by /root, not re-read by this subagent.','note_ids':';'.join(dict.fromkeys(n for i in selected for n in i['sources']))})
L('7:061–064',[(5,s) for s in range(28,32)],['restricted_sites','cech_nerve','local_cohomology'],'cette rétraction n’entre pas dans la structure; ind-représentable; à vérifier; si X est affine','Restricted locally retractive PD site, two-index diagonal envelope system, local cohomology and affine inverse-limit step; preserve distinction from ordinary infinitesimal site.')
L('7:070–072',[(5,29),(5,37)],['restricted_sites','ordinary_derham_examples','local_m3','ordinary_derham_counterexample'],'Si X est ... lisse; Lemme de Poincaré vrai; d_(A/k)x=0','Formal-smooth comparison and ordinary finite-algebra tests. The non-graded Artin counterexample concerns ordinary Kähler de Rham, not completed diagonals.')
L('7:072;8:054–056,073',[(5,51),(5,52)],['naive_padic_comparison','analytic_etale_comparison','true_padic_cohomology'],'un excès d’optimisme; j’ai de grands doutes; vraie cohomologie p-adique','Nonarchimedean Poincaré and constant-Z_p doubts precede the convergence/analytic questions; no period-sheaf theorem attributed to the letter.')
L('8:046',[(5,11),(5,13),(5,47)],['legendre','valuation_ideas','dvr_pd'],'v_p(n!)=(n−Σa_i)/(p−1); e≤p−1','Factorial digit valuations distinguish weak PD-existence threshold from strict PD-nilpotence/convergence threshold.')
L('8:002,004,010',[(6,5),(6,8),(6,9),(6,23)],['evaluation_nonfaithful','dieudonne_families','h1_dieudonne'],'module de type fini; devrait permettre; C’est bien celui défini par Dieudonné','W-module models, proposed F/V structures and H¹ Dieudonné identification; ordinary/PD crystalline distinction and later corrections retained.')
L('8:012,018',[(6,8),(6,9),(6,23)],['dieudonne_families','h1_dieudonne','fv_readings'],'FV=p; VF=id; C’est bien celui défini par Dieudonné','Integral F/V and H¹ comparison; literal asymmetric relation is a reading alarm, not silently normalized.')
L('8:025–027',[(6,s) for s in range(12,17)]+[(6,31),(6,34),(6,35)],['effective_lattices','nilinvariance_lifts','proper_algebraization','generic_essential_image','frobenius_lift','bt_universal_extension','ordinary_elliptic_extension','supersingular_open_image'],'il faut et il suffit; hypothèse évidemment bien restrictive; un sous-groupe ouvert','Stable lattices, dependence on lifts and generic essential image meet universal-extension and elliptic period/image questions. Pointwise lattice proof does not solve families.')
L('8:034–044',[(6,s) for s in range(10,13)]+[(6,25),(6,30),(6,32)],['isogeny_rationalization','effective_lattices','serre_tate_deformation','ordinary_retreat','recover_tate'],'nouveaux Hom; c’est une pure tautologie; module de Tate','Rational F/V data, effective lattices, ordinary deformation retreat and requested reconstruction of the integral Tate module; these are distinct levels of information.')
L('8:046–050',[(6,24),(6,25),(6,31),(6,32)],['hodge_deformation','serre_tate_deformation','bt_universal_extension','adic_bt_deformation','recover_tate'],'un relèvement de la filtration; Il serait bien intéressant d’essayer de déterminer','Hodge filtration deformation and universal extension motivate ramified integral reconstruction. Grothendieck–Messing needs compatible nilpotent PD thickenings.')
L('8:052–056,061',[(6,32)],['adic_bt_deformation','recover_tate'],'par passage à la limite; quel est le module de Tate correspondant','The complete-adic passage and Tate-module recovery question; rational filtered invariants alone do not specify an arbitrary integral Tate lattice.')
with (ROOT/'root_crosslinks.tsv').open('w') as f:
    w=csv.DictWriter(f,fieldnames=['kind','from','to','what','evidence','note_ids'],delimiter='\t');w.writeheader();w.writerows(rows)
print(f'Saved {len(rows)} root-requested endpoint correspondences.')
